class Solution {
public:
    bool areOccurrencesEqual(string s) {
        int frequency[26] = {};
        for (char c : s) {
            ++frequency[c - 'a'];
        }

        int expected = frequency[s[0] - 'a'];
        for (int count : frequency) {
            if (count != 0 && count != expected) {
                return false;
            }
        }

        return true;
    }
};
